import java.util.*;import java.util.function.*;public class DiscountEngine{public static void main(String[]x){List<Double> prices=List.of(100.0,250.0,500.0);Map<Integer,UnaryOperator<Double>> rules=Map.of(1,p->p*.90,2,p->p-50);Scanner s=new Scanner(System.in);System.out.print("Rule (1=10% off, 2=50 off): ");int k=s.nextInt();UnaryOperator<Double> f=rules.getOrDefault(k,UnaryOperator.identity());prices.forEach(p->System.out.println(p+" -> "+f.apply(p)));}}
